    grid = [[-1]*n for _ in range(n)]

    # Set diagonal
    for i in range(n):
        grid[i][i] = i

    # Track used values in each row and column
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    for i in range(n):
        row_used[i].add(i)
        col_used[i].add(i)

    # Get list of cells to fill (excluding diagonal)
    cells = [(i, j) for i in range(n) for j in range(n) if i != j]

    def is_valid(i, j, val):
        if val in row_used[i] or val in col_used[j]:
            return False
        return True

    def check_qg3_partial():
        # Check QG3 constraint for all fully determined triples
        for i in range(n):
            for j in range(n):
