                b = grid[j][i]
                if a >= 0 and b >= 0 and grid[a][b] >= 0:
                    if grid[a][b] != i:
                        return False
        return True

    def solve(idx):
        if idx == len(cells):
            return True

        i, j = cells[idx]

        for val in range(n):
