def solve_qg3_sat(n):
    """Encode as SAT problem"""
    # Variables: x_{i,j,v} means cell (i,j) has value v
    # Total variables: n * n * n

    def var(i, j, v):
        return i * n * n + j * n + v + 1  # 1-indexed for SAT

    solver = Glucose3()

    # Each cell has exactly one value
    for i in range(n):
        for j in range(n):
            # At least one value
            solver.add_clause([var(i, j, v) for v in range(n)])
            # At most one value (pairwise)
            for v1 in range(n):
                for v2 in range(v1+1, n):
                    solver.add_clause([-var(i, j, v1), -var(i, j, v2)])

    # Each row has each value exactly once
    for i in range(n):
        for v in range(n):
            # At least one cell in row i has value v
            solver.add_clause([var(i, j, v) for j in range(n)])
            # At most one
            for j1 in range(n):
                for j2 in range(j1+1, n):
                    solver.add_clause([-var(i, j1, v), -var(i, j2, v)])

    # Each column has each value exactly once
    for j in range(n):
        for v in range(n):
            solver.add_clause([var(i, j, v) for i in range(n)])
            for i1 in range(n):
                for i2 in range(i1+1, n):
                    solver.add_clause([-var(i1, j, v), -var(i2, j, v)])

    # Idempotent diagonal
    for i in range(n):
        solver.add_clause([var(i, i, i)])

    # QG3: x[x[i][j]][x[j][i]] = i
    # For each (i,j), and for each possible (a,b), if x[i][j]=a and x[j][i]=b, then x[a][b]=i
    for i in range(n):
        for j in range(n):
            for a in range(n):
                for b in range(n):
                    # If x[i][j]=a AND x[j][i]=b, then x[a][b]=i
                    # Equivalent to: NOT(x[i][j]=a) OR NOT(x[j][i]=b) OR x[a][b]=i
                    solver.add_clause([-var(i, j, a), -var(j, i, b), var(a, b, i)])

    print(f"Solving SAT for n={n}...")
    if solver.solve():
        model = solver.get_model()
        grid = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for v in range(n):
                    if var(i, j, v) in model:
                        grid[i][j] = v
                        break
        return grid
    else:
        return None

